def gen_pairs(lines,n=16):
 out=set()
 for i,(u1,(lo1,hi1)) in enumerate(lines):
  for u2,(lo2,hi2) in lines[i+1:]:
   vlo=max(lo1,lo2);vhi=min(hi1,hi2)
   if vlo>vhi: continue
   for r in range(n):
    for c0 in range(n):
     u=r+c0;v=r-c0
     if u1<u<u2 and vlo<=v<=vhi: out.add((r,c0))
 return out
